  const ok = Boolean(body && typeof body === 'object' && body.id !== undefined && !body.error);
  return { key, ok, id: ok ? String(body.id) : null, error: ok ? null : String((body && (body.message || (body.error && body.error.message) || body.error)) || 'create_failed').slice(0, 200) };
}

// ---- src/core/regression.js (embedded by scripts/build-workflow.js) ----
/**
 * Regression detection, regression-reason checks and audit records. Pure functions.
 */

/**
 * A reason counts only when it is long enough and was written after the deal entered the later
 * stage it fell back from. A reason left over from an earlier regression is "stale".
 */
function evaluateReason(history, currentValue, enteredPreviousAt, config) {
  const latest = latestPropertyValue(history, currentValue);
  if (latest.value.length < config.reason.minLength) return { status: 'missing', value: latest.value || null, updatedAt: latest.timestamp };
  if (latest.timestamp !== null && latest.timestamp < enteredPreviousAt) return { status: 'stale', value: latest.value, updatedAt: latest.timestamp };
  return { status: 'provided', value: latest.value, updatedAt: latest.timestamp };
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

/**
 * Evaluates every event against its deal. Returns one evaluation per event:
 * { eventId, dealId, outcome, transition, change, reason, deal } where outcome is
 * regression | not_regression | skipped.
 */
function evaluateEvents(events, deals, index, config) {
  const dealsById = Object.fromEntries(deals.map((deal) => [deal.dealId, deal]));
  const seenChanges = new Set();
  return events.map((event) => {
    const base = { eventId: event.eventId, dealId: event.dealId, source: event.source };
    const deal = dealsById[event.dealId];
    if (!deal || !deal.found) return { ...base, outcome: 'skipped', skipReason: deal ? `deal_not_readable: ${deal.error}` : 'deal_not_read' };
    const change = locateStageChange(deal.history.dealstage, event);
    if (!change.found) return { ...base, outcome: 'skipped', skipReason: change.reason };
    const key = `${event.dealId}:${change.changedAt}`;
    if (seenChanges.has(key)) return { ...base, outcome: 'skipped', skipReason: 'duplicate_change_in_batch' };
    seenChanges.add(key);
    const transition = classifyTransition(change.previousStageId, change.newStageId, index, config.detection);
    const pipelineId = transition.next ? transition.next.pipelineId : null;
    if (config.detection.pipelineIds.length && pipelineId && !config.detection.pipelineIds.includes(pipelineId)) {
      return { ...base, outcome: 'skipped', skipReason: 'pipeline_not_monitored' };
    }
    if (!transition.regression) return { ...base, outcome: 'not_regression', transitionType: transition.type, change };
    const reason = evaluateReason(deal.history[config.reason.property], deal.properties[config.reason.property], change.enteredPreviousAt, config);
    return { ...base, outcome: 'regression', transition, change, reason, deal: { properties: deal.properties } };
  });
}

/** Regressions whose reason is still missing or stale get a second look after the grace period. */
function dealsNeedingRecheck(evaluations) {
  return [...new Set(evaluations.filter((entry) => entry.outcome === 'regression' && entry.reason.status !== 'provided').map((entry) => entry.dealId))];
}

/** Applies re-read reason data ({ dealId, found, properties, history }) gathered after the grace period. */
function applyReasonRechecks(evaluations, rechecks, config) {
  const byId = Object.fromEntries(rechecks.filter((entry) => entry.found).map((entry) => [entry.dealId, entry]));
  return evaluations.map((entry) => {
    if (entry.outcome !== 'regression' || entry.reason.status === 'provided' || !byId[entry.dealId]) return entry;
    const recheck = byId[entry.dealId];
    const reason = evaluateReason(recheck.history[config.reason.property], recheck.properties[config.reason.property], entry.change.enteredPreviousAt, config);
    return { ...entry, reason: { ...reason, rechecked: true } };
  });
}

function numberOrNull(value) {
  const number = Number(value);
  return value === undefined || value === null || value === '' || !Number.isFinite(number) ? null : number;
}

/** Turns regression evaluations into audit table records. */
function buildAuditRecords(evaluations, owners, portal, config, now) {
  return evaluations.filter((entry) => entry.outcome === 'regression').map((entry) => {
    const properties = entry.deal.properties;
    const owner = owners.byOwnerId[text(properties.hubspot_owner_id)] || null;
    const changedBy = entry.change.changedByUserId ? owners.byUserId[entry.change.changedByUserId] || null : null;
    const regressedAt = new Date(entry.change.changedAt).toISOString();
    return {
      auditKey: `${entry.dealId}:${entry.change.changedAt}`,
      eventId: entry.eventId,
      dealId: entry.dealId,
      dealName: text(properties.dealname) || `Deal ${entry.dealId}`,
      dealUrl: dealUrl(portal, entry.dealId),
      pipeline: entry.transition.next.pipelineLabel,
      previousStage: entry.transition.previous.label,
      previousStageId: entry.transition.previous.id,
      newStage: entry.transition.next.label,
      newStageId: entry.transition.next.id,
      transitionType: entry.transition.type,
      stepsBack: entry.transition.stepsBack,
      severity: entry.transition.severity,
      amount: numberOrNull(properties.amount),
      currency: text(properties.deal_currency_code) || null,
      ownerId: owner ? owner.ownerId : (text(properties.hubspot_owner_id) || null),
      ownerName: owner ? owner.name : (text(properties.hubspot_owner_id) ? `Owner ${text(properties.hubspot_owner_id)}` : 'Unassigned'),
      ownerEmail: owner ? owner.email : null,
      changedBy: changedBy ? changedBy.name : (entry.change.changedByUserId ? `User ${entry.change.changedByUserId}` : (entry.change.sourceType || 'unknown')),
      changeSource: entry.change.sourceType,
      regressedAt,
      detectedAt: new Date(now).toISOString(),
      reason: entry.reason.value,
      reasonStatus: entry.reason.status,
      reasonRechecked: Boolean(entry.reason.rechecked),
      runMode: config.dryRun ? 'dry_run' : config.sandboxMode ? 'sandbox' : 'live',
    };
  });
}

function summarizeEvaluations(evaluations) {
  const counters = { events: evaluations.length, regressions: 0, reasonProvided: 0, reasonMissing: 0, reasonStale: 0, notRegression: 0, skipped: 0 };
  const skipReasons = {};
  for (const entry of evaluations) {
    if (entry.outcome === 'regression') {
      counters.regressions += 1;
      if (entry.reason.status === 'provided') counters.reasonProvided += 1;
      else if (entry.reason.status === 'stale') counters.reasonStale += 1;
      else counters.reasonMissing += 1;
    } else if (entry.outcome === 'not_regression') counters.notRegression += 1;
    else {
      counters.skipped += 1;
      skipReasons[entry.skipReason] = (skipReasons[entry.skipReason] || 0) + 1;
    }
  }
  return { ...counters, skipReasons };
}

/** Records that leadership should hear about, after ALERT_MIN_SEVERITY, ALERT_MIN_AMOUNT and ALERT_ONLY_MISSING_REASON. */
function recordsToAlert(records, config) {
  return records.filter((record) => {
    if (config.alerts.minSeverity === 'high' && record.severity !== 'high') return false;
    if (config.alerts.minAmount > 0 && (record.amount === null || record.amount < config.alerts.minAmount)) return false;
    if (config.alerts.onlyMissingReason && record.reasonStatus === 'provided') return false;
    return true;
  });
}

/** Owner tasks for regressions without a valid reason (only when CREATE_OWNER_TASKS=true and an owner exists). */
function recordsNeedingTasks(records, config) {
  if (!config.tasks.enabled) return [];
  return records.filter((record) => record.reasonStatus !== 'provided' && Boolean(record.ownerId));
}

// ---- src/core/auditTable.js (embedded by scripts/build-workflow.js) ----
/**
 * The audit tracking table.
 * - static (default): the last STATIC_AUDIT_ROW_LIMIT rows in n8n workflow static data (no setup).
 * - airtable: upserts into an Airtable table keyed on "Audit Key", so retried webhooks never duplicate rows.
 * Request objects never carry the Airtable token; the HTTP node adds it from $env.
 */

const AIRTABLE_FIELDS = Object.freeze({
  auditKey: 'Audit Key',
  dealId: 'Deal ID',
  dealName: 'Deal Name',
  dealUrl: 'Deal URL',
  pipeline: 'Pipeline',
  previousStage: 'Previous Stage',
  newStage: 'New Stage',
  transitionType: 'Transition',
  stepsBack: 'Steps Back',
  severity: 'Severity',
  amount: 'Amount',
  currency: 'Currency',
  ownerName: 'Owner',
  ownerEmail: 'Owner Email',
  changedBy: 'Changed By',
  changeSource: 'Change Source',
  regressedAt: 'Regressed At',
  detectedAt: 'Detected At',
  reason: 'Regression Reason',
  reasonStatus: 'Reason Status',
  runMode: 'Run Mode',
});

const AIRTABLE_BATCH_SIZE = 10;

function toAirtableFields(record, config) {
  const fields = {};
  for (const [key, column] of Object.entries(AIRTABLE_FIELDS)) {
    if (key === 'ownerEmail' && !config.audit.includeOwnerEmail) continue;
    const value = record[key];
    if (value === null || value === undefined || value === '') continue;
    fields[column] = value;
  }
  return fields;
}

function buildAirtableUpsertRequests(records, config) {
  const url = `${config.audit.airtableBaseUrl}/v0/${encodeURIComponent(config.audit.airtableBaseId)}/${encodeURIComponent(config.audit.airtableTable)}`;
  const requests = [];
  for (let index = 0; index < records.length; index += AIRTABLE_BATCH_SIZE) {
    const batch = records.slice(index, index + AIRTABLE_BATCH_SIZE);
    requests.push({
      auditKeys: batch.map((record) => record.auditKey),
      request: {
        method: 'PATCH',
        url,
        body: { performUpsert: { fieldsToMergeOn: [AIRTABLE_FIELDS.auditKey] }, typecast: true, records: batch.map((record) => ({ fields: toAirtableFields(record, config) })) },
      },
    });
  }
  return requests;
}

function parseAirtableResponse(plan, body) {
  const ok = Boolean(body && Array.isArray(body.records) && !body.error);
  return {
    auditKeys: plan.auditKeys,
    ok,
    created: ok && Array.isArray(body.createdRecords) ? body.createdRecords.length : 0,
    updated: ok && Array.isArray(body.updatedRecords) ? body.updatedRecords.length : 0,
    error: ok ? null : String((body && body.error && (body.error.message || body.error.type || body.error)) || 'airtable_write_failed').slice(0, 200),
  };
}

/** Upserts rows into the static-data table, newest first, capped at STATIC_AUDIT_ROW_LIMIT. */
function appendStaticRows(state, records, config) {
  const table = state.regressionAuditRows || (state.regressionAuditRows = []);
  for (const record of records) {
    const index = table.findIndex((row) => row.auditKey === record.auditKey);
    const row = { ...record };
    if (!config.audit.includeOwnerEmail) delete row.ownerEmail;
    if (index >= 0) table.splice(index, 1);
    table.unshift(row);
  }
  table.splice(config.audit.staticRowLimit);
  return table.length;
}

/** Daily counters (30 days) for dashboards and the run summary. */
function recordDailyCounters(state, counters, now) {
  const store = state.regressionDailyCounters || (state.regressionDailyCounters = {});
  const day = new Date(now).toISOString().slice(0, 10);
  const bucket = store[day] || (store[day] = { runs: 0 });
  bucket.runs += 1;
  for (const [key, value] of Object.entries(counters)) if (typeof value === 'number') bucket[key] = (bucket[key] || 0) + value;
  const cutoff = new Date(now - 30 * 86400000).toISOString().slice(0, 10);
  for (const key of Object.keys(store)) if (key < cutoff) delete store[key];
  return bucket;
}

/** Run totals shared by the n8n workflow and the Node.js mirror. */
function buildRunTotals({ counters, auditResults = [], taskCandidates = [], taskResults = [], alerted = [] }) {
  const { skipReasons, ...numeric } = counters;
  return {
    ...numeric,
    auditRowsWritten: auditResults.filter((result) => result.ok).reduce((sum, result) => sum + result.auditKeys.length, 0),
    auditWriteFailures: auditResults.filter((result) => !result.ok).length,
    tasksPlanned: taskCandidates.length,
    tasksCreated: taskResults.filter((result) => result.ok).length,
    taskFailures: taskResults.filter((result) => !result.ok).length,
    alerted: alerted.length,
  };
}

// ---- src/core/slack.js (embedded by scripts/build-workflow.js) ----
/**
 * Leadership alerts and redacted failure alerts (Slack Block Kit).
 */

const REASON_LABEL = { provided: ':white_check_mark: reason provided', missing: ':warning: *reason missing*', stale: ':warning: *reason stale* (left over from an earlier regression)' };
const TYPE_LABEL = { regression: 'moved back', reopened: 'reopened', closed_reversal: 'closed-won reversed', pipeline_change: 'moved pipeline' };

function escapeSlack(text) {
  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function formatAmount(record) {
  if (record.amount === null || record.amount === undefined) return null;
  const formatted = Number(record.amount).toLocaleString('en-US', { maximumFractionDigits: 0 });
  return record.currency ? `${formatted} ${record.currency}` : formatted;
}

function badges(config) {
  const list = [];
  if (config.mode === 'demo') list.push('DEMO DATA');
  if (config.dryRun) list.push('DRY RUN');
  if (config.sandboxMode) list.push('SANDBOX');
  return list;
}

function describeOutcome({ auditResults, taskResults, config }) {
  const parts = [];
  if (config.audit.provider === 'airtable') {
    if (config.dryRun) parts.push('audit rows kept in n8n only (DRY_RUN)');
    else parts.push(`${auditResults.filter((result) => result.ok).reduce((sum, result) => sum + result.auditKeys.length, 0)} audit row(s) upserted to Airtable${auditResults.some((result) => !result.ok) ? ', some failed' : ''}`);
  } else {
    parts.push('audit rows stored in n8n static data');
  }
  if (config.tasks.enabled) {
    if (config.dryRun) parts.push('owner tasks planned, not created (DRY_RUN)');
    else parts.push(`${taskResults.filter((result) => result.ok).length} owner task(s) created${taskResults.some((result) => !result.ok) ? `, ${taskResults.filter((result) => !result.ok).length} failed` : ''}`);
  }
  return parts.join(' · ');
}

function buildLeadershipAlert({ records, alerted, auditResults = [], taskResults = [], config, requestId }) {
  const missing = alerted.filter((record) => record.reasonStatus !== 'provided').length;
  const tag = badges(config);
  const headline = `${alerted.length} deal stage regression${alerted.length === 1 ? '' : 's'}${missing ? `, ${missing} without a valid reason` : ''}`;
  const text = `${tag.length ? `[${tag.join(' | ')}] ` : ''}Deal stage regression audit: ${headline}.`;
  const lines = alerted.slice(0, config.alerts.maxListed).map((record) => {
    const name = record.dealUrl ? `<${record.dealUrl}|${escapeSlack(record.dealName)}>` : `*${escapeSlack(record.dealName)}*`;
    const amount = formatAmount(record);
    const steps = record.transitionType === 'regression' ? ` (${record.stepsBack} stage${record.stepsBack === 1 ? '' : 's'} back)` : '';
    const reason = record.reasonStatus === 'provided' ? `${REASON_LABEL.provided}: _${escapeSlack(record.reason).slice(0, 200)}_` : REASON_LABEL[record.reasonStatus];
    return [
      `${record.severity === 'high' ? ':red_circle:' : ':large_orange_circle:'} ${name}${amount ? ` · ${escapeSlack(amount)}` : ''}`,
      `   ${escapeSlack(record.previousStage)} → ${escapeSlack(record.newStage)} · ${TYPE_LABEL[record.transitionType] || record.transitionType}${steps} · ${escapeSlack(record.pipeline)}`,
      `   Owner: ${escapeSlack(record.ownerName)} · changed by ${escapeSlack(record.changedBy)} · ${escapeSlack(record.regressedAt)}`,
      `   ${reason}`,
    ].join('\n');
  });
  const more = alerted.length > config.alerts.maxListed ? `\n_${alerted.length - config.alerts.maxListed} more in the audit table._` : '';
  const body = `${lines.join('\n\n')}${more}`;
  return {
    text,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: 'Deal stage regression audit', emoji: true } },
      { type: 'section', text: { type: 'mrkdwn', text: `${tag.length ? `*${tag.join('  ·  ')}*\n` : ''}*${escapeSlack(headline)}*` } },
      { type: 'section', text: { type: 'mrkdwn', text: body.length > 2900 ? `${body.slice(0, 2880)}\n_...shortened_` : body } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: `${escapeSlack(describeOutcome({ auditResults, taskResults, config }))} · ${records.length} regression(s) logged · request ${escapeSlack(requestId)}` }] },
    ],
  };
}

const SECRET_PATTERNS = [
  /Bearer\s+[A-Za-z0-9._~+/=-]+/gi,
  /pat-[a-z0-9]+-[A-Za-z0-9-]+/gi,
  /\bpat[A-Za-z0-9]{10,}\.[A-Za-z0-9]{20,}\b/g,
  /https:\/\/hooks\.slack\.com\/[^\s"']+/gi,
  /([?&](?:hapikey|api_key|token|access_token)=)[^&\s"']+/gi,
];

function redactSecrets(value, extraSecrets = []) {
  let output = String(value ?? '');
  for (const secret of extraSecrets) if (secret && String(secret).length >= 6) output = output.split(String(secret)).join('[redacted]');
  for (const pattern of SECRET_PATTERNS) output = output.replace(pattern, (match, prefix) => (typeof prefix === 'string' && /^[?&]/.test(prefix) ? `${prefix}[redacted]` : '[redacted]'));
  return output;
}

function buildFailureAlert({ errorMessage, lastNode, executionId, workflowName, config, secrets }) {
  const message = redactSecrets(errorMessage || 'Unknown error', secrets).slice(0, 1500);
  const label = config.dryRun || config.sandboxMode ? ' [DRY RUN / SANDBOX]' : '';
  return {
    text: `Deal stage regression audit failed${label}${lastNode ? ` in "${lastNode}"` : ''}.`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: 'Deal stage regression audit failed', emoji: true } },
      { type: 'section', text: { type: 'mrkdwn', text: `:x: Node: *${escapeSlack(lastNode || 'unknown')}*${label}\n\`\`\`${escapeSlack(message)}\`\`\`` } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: `Workflow ${escapeSlack(workflowName || 'n8n-hubspot-deal-stage-regression-audit-logger')} · execution ${escapeSlack(executionId || 'unknown')}` }] },
    ],
  };
}

