function createMockHubSpot({ deals = createDemoDeals(), account = { portalId: 'DEMO', accountType: 'SANDBOX', uiDomain: 'app.hubspot.com' }, pipelines = DEMO_PIPELINES, owners = DEMO_OWNERS, failTasks = false } = {}) {
